import{_ as e}from"./chunks/files.B17OUyrr.js";import{_ as t,c as r,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"比较文件","description":"并排打开两份文件，看颜色、跳改动，顺手编辑或分享。","frontmatter":{"title":"比较文件","description":"并排打开两份文件，看颜色、跳改动，顺手编辑或分享。"},"headers":[],"relativePath":"zh-CN/guide/files.md","filePath":"zh-CN/guide/files.md","lastUpdated":1793948370000}'),l={name:"zh-CN/guide/files.md"};function s(n,a,d,h,c,p){return i(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="比较文件" tabindex="-1">比较文件 <a class="header-anchor" href="#比较文件" aria-label="Permalink to &quot;比较文件&quot;">​</a></h1><p>大多数人都是从这里开始的：同一份文件的两个版本并排放好，不同的地方全部标出来。</p><img src="'+e+'" alt="两份文本文件并排比较，改动带有颜色" class="guide-shot"><h2 id="打开两份文件" tabindex="-1">打开两份文件 <a class="header-anchor" href="#打开两份文件" aria-label="Permalink to &quot;打开两份文件&quot;">​</a></h2><p>用菜单「文件 → 打开」，或者直接把两个文件拖进 qDiff 窗口。要对照三个版本？ 再加一栏就好，颜色规则一样。最近比过的内容会留在欢迎页，下次一点就回来。</p><h2 id="颜色是什么意思" tabindex="-1">颜色是什么意思 <a class="header-anchor" href="#颜色是什么意思" aria-label="Permalink to &quot;颜色是什么意思&quot;">​</a></h2><ul><li><strong>淡红</strong> —— 这一侧的内容被删掉了，或者属于旧版本。</li><li><strong>淡绿</strong> —— 这一侧是新增的，或者属于新版本。</li><li><strong>行里更深的一小块</strong> —— 具体改动的那几个字。哪怕一行只改了一个字， 也不会被整行颜色盖住。</li></ul><p>两侧会同步滚动，永远停在同一行上。</p><h2 id="在改动之间跳转" tabindex="-1">在改动之间跳转 <a class="header-anchor" href="#在改动之间跳转" aria-label="Permalink to &quot;在改动之间跳转&quot;">​</a></h2><p>点文字旁边那条细长的小地图，可以跳到文件任意位置；也可以用「上一处 / 下一处」 按钮（有快捷键）逐个查看。文件很长时，小地图还能告诉你当前看到哪儿了。</p><h2 id="边看边改" tabindex="-1">边看边改 <a class="header-anchor" href="#边看边改" aria-label="Permalink to &quot;边看边改&quot;">​</a></h2><p>两侧都能直接编辑、撤销。每一处改动都可以单独复制过去、替换或删除 —— 在比较 界面里就能做完，不用再打开别的编辑器。改完照常保存即可。</p><div class="tip custom-block"><p class="custom-block-title">分享成图片</p><p>选中一处改动，可以把它导出成一张干净的双栏图片，贴到聊天或评审里很方便， 导出的图片不带任何标记。</p></div><p>接下来：<a href="./folders.html">比较整个文件夹</a>。</p>',14)])])}const m=t(l,[["render",s]]);export{f as __pageData,m as default};
